module tree_checker (\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] n,\n    input edge_valid,\n    input [3:0] edge_u,\n    input [3:0] edge_v,\n    output reg result,\n    output reg done\n);\n\n    localparam [1:0] IDLE = 2'd0;\n    localparam [1:0] LOAD = 2'd1;\n    localparam [1:0] CHECK = 2'd2;\n\n    reg [1:0] state;\n    reg [3:0] deg [0:15];\n    reg [3:0] edge_count;\n    integer i;\n\n    wire has_deg2;\n    assign has_deg2 = \n        (deg[0]  == 4'd2) | (deg[1]  == 4'd2) | (deg[2]  == 4'd2) | (deg[3]  == 4'd2) |\n        (deg[4]  == 4'd2) | (deg[5]  == 4'd2) | (deg[6]  == 4'd2) | (deg[7]  == 4'd2) |\n        (deg[8]  == 4'd2) | (deg[9]  == 4'd2) | (deg[10] == 4'd2) | (deg[11] == 4'd2) |\n        (deg[12] == 4'd2) | (deg[13] == 4'd2) | (deg[14] == 4'd2) | (deg[15] == 4'd2);\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 1'b0;\n            edge_count <= 4'd0;\n            for (i = 0; i < 16; i = i + 1) begin\n                deg[i] <= 4'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= LOAD;\n                        edge_count <= 4'd0;\n                        for (i = 0; i < 16; i = i + 1) begin\n                            deg[i] <= 4'd0;\n                        end\n                    end\n                end\n\n                LOAD: begin\n                    if (edge_valid) begin\n                        deg[edge_u - 4'd1] <= deg[edge_u - 4'd1] + 4'd1;\n                        deg[edge_v - 4'd1] <= deg[edge_v - 4'd1] + 4'd1;\n                        edge_count <= edge_count + 4'd1;\n                        \n                        if (edge_count + 4'd1 == n - 4'd1) begin\n                            state <= CHECK;\n                        end\n                    end\n                end\n\n                CHECK: begin\n                    done <= 1'b1;\n                    result <= ~has_deg2;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule